fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn files(root:&Path,p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){files(root,&p,out)}else{out.push(p.strip_prefix(root).unwrap().to_path_buf());}}}
fn rows(p:impl AsRef<Path>)->(Vec<Value>,Value){let s=fs::read_to_string(p).unwrap();let rows=s.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|s|serde_json::from_str(s).unwrap()).collect();let done=s.lines().find_map(|l|l.strip_prefix("COMPLETE ")).map(|s|serde_json::from_str(s).unwrap()).unwrap();(rows,done)}
